start.source:
pub fn main() -> fn() -> Nil {
  mvu.start(init(), update, view)
}

update.source:
pub fn init() -> #(Model, List(Effect(Msg))) {
  #(Model(title: "Hello"), [])
}

pub fn update(model: Model, msg: Msg) -> #(Model, List(Effect(Msg))) {
  case msg {
    UserChangedTitle(title) -> #(
      Model(..model, title: title),
      [save_title(title)],
    )
    TitleSaved -> #(model, [])
    TitleSaveFailed -> #(model, [log("Could not save the title.")])
  }
}

view.source:
import { html, render } from 'lit-html'
import { live } from 'lit-html/directives/live.js'
import {
  Model$Model$title as title,
  UserChangedTitle,
} from './app.mjs'

export function view(model, dispatch) {
  const app = document.getElementById('app')
  if (!app) throw new Error('Missing #app mount element')

  render(html`
    <h1>${title(model)}</h1>
    <input .value=${live(title(model))}
      @input=${event => dispatch(new UserChangedTitle(event.currentTarget.value))}>
  `, app)
}

boundary.source:
@external(javascript, "./view.mjs", "view")
fn view(model: Model, dispatch: fn(Msg) -> Nil) -> Nil

@external(javascript, "./effects.mjs", "saveTitle")
fn save_title(title: String) -> Effect(Msg)

effect.source:
import {
  Msg$TitleSaved as titleSaved,
  Msg$TitleSaveFailed as titleSaveFailed,
} from './app.mjs'

export const saveTitle = title => ({
  perform: () => localStorage.setItem('title', title),
  onSuccess: () => titleSaved(),
  onFailure: () => titleSaveFailed(),
})

export const log = message => ({
  perform: () => console.log(message),
})

subscription.source:
export function every(milliseconds, onTick) {
  return {
    start: emit => {
      const timer = setInterval(() => emit(onTick(Date.now())), milliseconds)
      return () => clearInterval(timer)
    },
  }
}

manage.source:
import { every } from './subscriptions.mjs'
import { Msg$ClockTicked as clockTicked } from './app.mjs'

export const startClock = () => ({
  perform: ({ subscriptions, dispatch }) =>
    subscriptions.start('clock', every(1000, clockTicked), dispatch),
})

export const stopClock = () => ({
  perform: ({ subscriptions }) => subscriptions.stop('clock'),
})

